#!/bin/bash

# Start script for Get Notes MCP Server

# Check if .env file exists and load it
if [ -f ".env" ]; then
    export $(grep -v '^#' .env | xargs)
fi

# Check if API key is set
if [ -z "$GET_NOTE_API_KEY" ]; then
    echo "Error: GET_NOTE_API_KEY environment variable is not set"
    echo "Please set your API key: export GET_NOTE_API_KEY='your-api-key-here'"
    echo "Or run the auto-configuration script: ./scripts/auto-config-start.sh"
    exit 1
fi

# Create logs directory if it doesn't exist
mkdir -p logs

# Install dependencies if node_modules doesn't exist
if [ ! -d "node_modules" ]; then
    echo "Installing dependencies..."
    npm install
fi

# Start the server
echo "Starting Get Notes MCP Server..."
echo "API Key: ${GET_NOTE_API_KEY:0:8}..."
echo "Topic ID: ${GET_NOTE_TOPIC_ID:-Not set}"
echo "API Base URL: ${GET_NOTE_API_BASE_URL:-https://open-api.biji.com/getnote/openapi}"
echo "Log Level: ${LOG_LEVEL:-info}"
echo ""

node src/index.js